'use strict';
(function(root){function install(E){const P=E.Game.prototype;if(P.fusionRuntime)return;P.fusionRuntime=true;const old={action:P.performSkillAction,tech:P.tickTechniques,ready:P.autoSkillReady,cast:P.castSkill};const kinds=['fire','water','wind','earth'],active=g=>g.s.active===11&&g.h.cell===4,live=g=>g.c.enemies.filter(e=>e.hp>0),units=g=>g.c.devices.filter(p=>p.fourElement&&p.life>0),fused=g=>units(g).find(p=>p.appearance==='fusion');
function spawn(g,kind,ctx){const i=kinds.indexOf(kind),fusion=kind==='fusion',pos=E.safePoint({x:g.c.x+55+(i%2)*42,y:g.c.y-45+Math.floor(i/2)*70},g.c.zone);const p={...pos,kind:'spirit',fourElement:true,undead:true,appearance:fusion?'fusion':kind,skin:fusion?'fusion':'element-'+kind,name:fusion?'사원소 융합체':{fire:'불꽃 정령',water:'물방울 정령',wind:'돌풍 정령',earth:'바위 정령'}[kind],life:fusion?32:24,timer:.15*Math.max(0,i),lastAttack:-99,renderHeight:fusion?78:kind==='earth'?44:38,damage:ctx.attack,ctx,petHP:1e9,maxPetHP:1e9};g.c.devices.push(p);return p;}
function strike(g,p,element,t,multi=1){if(!t||t.hp<=0)return;const c=g.c,ctx=p.ctx,power=element==='earth'?1.5:element==='fire'?.9:element==='water'?.65:.8,hit=e=>g.damageTechnique(e,power*multi,ctx);if(element==='fire'){for(const e of live(g).filter(e=>E.dist(e,t)<85))hit(e);}else if(element==='water'){hit(t);t.fusionSlow=Math.max(t.fusionSlow||0,2.5);}else if(element==='wind'){const dx=t.x-p.x,dy=t.y-p.y,len=Math.hypot(dx,dy)||1;for(const e of live(g)){const along=((e.x-p.x)*dx+(e.y-p.y)*dy)/len,side=Math.abs((e.x-p.x)*dy-(e.y-p.y)*dx)/len;if(along>=0&&along<=340&&side<24)hit(e);}}else{for(const e of live(g).filter(e=>E.dist(e,t)<65)){hit(e);e.root=Math.max(e.root||0,e.boss?.18:.5);}}p.lastAttack=g.time;g.emit('skill',{...ctx.event,heroId:11,cell:4,phase:true,element,from:{x:p.x,y:p.y-18},x:t.x,y:t.y,fusionHit:true});}
function combo(g,p,boost,ultimate=false){const c=g.c;for(let i=0;i<4;i++)g.queueSkill(i*.28,()=>{if(g.c!==c||c.hp<=0||c.deadTimer>0||c.transition>0||!units(g).includes(p))return;const t=live(g).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(t&&E.dist(p,t)<420)strike(g,p,kinds[i],t,boost);});if(ultimate)g.queueSkill(1.35,()=>{if(g.c!==c||c.hp<=0||c.deadTimer>0||c.transition>0||!units(g).includes(p))return;const t=live(g).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(!t||E.dist(p,t)>420)return;for(const e of live(g).filter(e=>E.dist(e,t)<160))g.damageTechnique(e,4,p.ctx);g.emit('skill',{...p.ctx.event,heroId:11,cell:4,phase:true,element:'all',from:{x:p.x,y:p.y-18},x:t.x,y:t.y});});}
P.performSkillAction=function(a,ctx){if(a.op!=='fusion-kit')return old.action.call(this,a,ctx);const c=this.c;if(c!==ctx.combat||c.hp<=0)return;switch(a.kind){case'four-call':c.devices=c.devices.filter(p=>!p.fourElement);for(const k of kinds)spawn(this,k,ctx);break;case'merge':{if(fused(this)||!kinds.every(k=>units(this).some(p=>p.appearance===k)))return;c.devices=c.devices.filter(p=>!p.fourElement);spawn(this,'fusion',ctx);break;}case'resonance':{const p=fused(this);if(p){p.ctx=ctx;combo(this,p,1.4);}break;}case'overdrive':{const p=fused(this);if(p){p.ctx=ctx;p.overdrive=8;p.life=Math.max(p.life,10);combo(this,p,2,true);}break;}}};
P.autoSkillReady=function(d,t){if(d.actions[0]?.op==='fusion-kit'){const k=d.actions[0].kind,p=fused(this);if(k==='four-call'&&units(this).length)return false;if(k==='merge'&&(p||!kinds.every(k=>units(this).some(p=>p.appearance===k))))return false;if(['resonance','overdrive'].includes(k)&&!p)return false;}return old.ready.call(this,d,t);};
P.castSkill=function(slot,manual=true){const d=this.skillSpec(slot);if(active(this)&&d?.actions[0]?.op==='fusion-kit'&&!this.autoSkillReady(d,null))return false;return old.cast.call(this,slot,manual);};
P.tickTechniques=function(dt){const c=this.c,ps=c.devices.filter(p=>p.fourElement);for(const e of live(this))e.fusionSlow=Math.max(0,(e.fusionSlow||0)-dt);c.devices=c.devices.filter(p=>!p.fourElement);const result=old.tech.call(this,dt);for(const p of ps){p.life-=dt;p.timer-=dt;p.overdrive=Math.max(0,(p.overdrive||0)-dt);if(p.life<=0)continue;const t=live(this).sort((a,b)=>E.dist(p,a)-E.dist(p,b))[0];if(!t)continue;const range=p.appearance==='earth'?55:260,d=E.dist(p,t);p.facing=t.x<p.x;if(d>range){const step=Math.min(dt*75,d-range),pos=E.safePoint({x:p.x+(t.x-p.x)/d*step,y:p.y+(t.y-p.y)/d*step},c.zone);p.x=pos.x;p.y=pos.y;}if(d<=range+8&&p.timer<=0){if(p.appearance==='fusion'){p.elementIndex=((p.elementIndex??-1)+1)%4;strike(this,p,kinds[p.elementIndex],t,p.overdrive>0?1.8:1.2);p.timer=p.overdrive>0?.5:1;}else{strike(this,p,p.appearance,t);p.timer=p.appearance==='earth'?1.7:1.3;}}}c.devices=c.devices.concat(ps.filter(p=>p.life>0));return result;};
}if(typeof module!=='undefined')module.exports=install;root.RPG_FUSION_RUNTIME={install};})(typeof window!=='undefined'?window:globalThis);
